import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.D5wUhsuj.js";const g=JSON.parse('{"title":"PhyAgentOS 框架介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh/01-framework-introduction.md","filePath":"zh/01-framework-introduction.md"}'),s={name:"zh/01-framework-introduction.md"};function o(l,e,c,d,r,p){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="phyagentos-框架介绍" tabindex="-1">PhyAgentOS 框架介绍 <a class="header-anchor" href="#phyagentos-框架介绍" aria-label="Permalink to &quot;PhyAgentOS 框架介绍&quot;">​</a></h1><p><a href="/docs/en/01-framework-introduction">English</a> · <a href="/docs/">文档索引</a></p><blockquote><p>文档版本：1.0.0 · 实现基线：2026-08-30 源码、配置 Schema 与测试。</p></blockquote><h2 id="_1-项目定位" tabindex="-1">1. 项目定位 <a class="header-anchor" href="#_1-项目定位" aria-label="Permalink to &quot;1. 项目定位&quot;">​</a></h2><p>PhyAgentOS 是面向具身任务的 Agent 框架。Agent 理解用户目标、选择 Forge Tool、定义任务级 成功标准，并决定继续还是恢复；Forge Gateway 负责 Tool 执行、ToolEndpoint 选择、Dora 集成以及机器人或仿真器访问。</p><p>该边界把认知规划与物理效果分离。通用 Agent tools、verification、任务经验、evolution、 Skill activation 和动态 MCP 工具继续属于 Agent 平台；机器人动作统一使用 Forge Query/Action/Session Tool API。</p><h2 id="_2-唯一物理执行面" tabindex="-1">2. 唯一物理执行面 <a class="header-anchor" href="#_2-唯一物理执行面" aria-label="Permalink to &quot;2. 唯一物理执行面&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 / 消息渠道 / 定时事件</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>      AgentLoop + Planner</span></span>
<span class="line"><span>              │  绑定 AgentTask 或诊断 Query</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>       ForgeToolClient ─────────► AgentTask SQLite + evidence</span></span>
<span class="line"><span>              │                         │</span></span>
<span class="line"><span>              │ HTTP Tool API           ▼</span></span>
<span class="line"><span>              ▼                  ForgeTaskVerifier</span></span>
<span class="line"><span> Gateway /tools → ToolInvocation        │</span></span>
<span class="line"><span>              │                  verdict / PlanRevision</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span> ToolEndpoint → Dora → 机器人/仿真器</span></span>
<span class="line"><span></span></span>
<span class="line"><span>终结 AgentTask ───────► Experience Coordinator ──► evolution ledger</span></span></code></pre></div><p>绑定调用和诊断 Query 经过相同 Gateway endpoint；诊断 Query 不占 AgentTask 槽位，Action 与 task-owned Session 必须使用冻结的 task binding。PAOS 不增加跨 Tool 资源租约，由所选 endpoint operation 的 <code>max_concurrency</code> 决定接纳结果。</p><h2 id="_3-三类事实" tabindex="-1">3. 三类事实 <a class="header-anchor" href="#_3-三类事实" aria-label="Permalink to &quot;3. 三类事实&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">事实</th><th style="text-align:left;">责任方</th><th style="text-align:left;">回答的问题</th></tr></thead><tbody><tr><td style="text-align:left;">Execution</td><td style="text-align:left;">Forge Gateway</td><td style="text-align:left;">哪个 Query 已完成，或哪个 Action/Session invocation 被接纳并如何终结？</td></tr><tr><td style="text-align:left;">Evidence</td><td style="text-align:left;">PAOS observation collector</td><td style="text-align:left;">Task-owned 物理执行前后观察到了什么？</td></tr><tr><td style="text-align:left;">Verdict</td><td style="text-align:left;">PAOS verification</td><td style="text-align:left;">全部绑定调用是否满足用户目标、criteria 与 constraints？</td></tr></tbody></table><p>Action/Session admission 不是完成。取消或停止被接受、本地超时或 <code>unknown</code> 结果都不能证明物理执行已经 停止，也不能作为盲目重试的依据。</p><h2 id="_4-身份模型" tabindex="-1">4. 身份模型 <a class="header-anchor" href="#_4-身份模型" aria-label="Permalink to &quot;4. 身份模型&quot;">​</a></h2><p>以下标识有意保持不同：</p><ul><li><code>task_id</code>：一个用户可见目标对应的 AgentTask 聚合；</li><li><code>binding_id</code>：一份不可变 Skill/Runtime/ToolSpec 快照；</li><li><code>revision_id</code>：任务内一次不可变规划世代；</li><li>Query/execution <code>record_id</code>：挂在 revision 下的一条 PAOS record；</li><li><code>caller_id</code>：异步 admission 前持久化的 PAOS 生成身份；</li><li><code>invocation_id</code>：Gateway 拥有的异步 Action 或 Session invocation；</li><li><code>attempt_id</code>：Gateway 的一次执行尝试。</li></ul><p>这些 ID 不能互相复制或视为别名。Forge 对 Tool 执行事实负责；AgentTask 只保存引用和任务级 解释。</p><h2 id="_5-agenttask-生命周期" tabindex="-1">5. AgentTask 生命周期 <a class="header-anchor" href="#_5-agenttask-生命周期" aria-label="Permalink to &quot;5. AgentTask 生命周期&quot;">​</a></h2><p>全局最多一个非终态 AgentTask。任务从 revision 1 开始，可包含多个绑定 Query、Action 与 Session。 PlanRevision 只追加，既有 execution record 和 verification attempt 不会被重写。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>executing ── finalize success ──► succeeded</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── finalize failure ───────► failed</span></span>
<span class="line"><span>    ├── recovery verdict ───────► awaiting_replan ── begin revision ──► executing</span></span>
<span class="line"><span>    └── cancel request ─────────► cancelling ── reconcile + finalize ─► cancelled/failed</span></span></code></pre></div><p>Task tools 负责创建、读取、修订、finalize 与取消聚合；Tool API tools 读取 Tool context、调用 Query/Action/Session、核对异步 status/result，并请求 cancel/stop。</p><h2 id="_6-验证与恢复" tabindex="-1">6. 验证与恢复 <a class="header-anchor" href="#_6-验证与恢复" aria-label="Permalink to &quot;6. 验证与恢复&quot;">​</a></h2><p>验证模式为 <code>off</code>、<code>audit</code>、<code>enforce</code> 和 <code>recovery</code>。</p><ul><li><code>off</code> 根据绑定执行事实派生成功，不调用语义验证；</li><li><code>audit</code> 记录 verdict，但保留执行派生终态语义；</li><li><code>enforce</code> 要求合法任务契约，遇到缺证、非法输出、服务错误或 inconclusive 时 fail closed；</li><li><code>recovery</code> 同样 fail closed，并允许返回 <code>replan_required</code>。</li></ul><p>恢复在相同 <code>task_id</code> 上追加有预算的 PlanRevision。Planner 接收 unmet criteria、保留约束、 guidance、evidence references 和 deadline，再重新选择 Tool。未知 Action 效果只能按已持久化 invocation ID 核实，PAOS 不会重复未知 admission POST。</p><h2 id="_7-evidence" tabindex="-1">7. Evidence <a class="header-anchor" href="#_7-evidence" aria-label="Permalink to &quot;7. Evidence&quot;">​</a></h2><p>PAOS 通过 Gateway WebSocket 采集配置的图像源和可选 robot state，使用有界最新帧缓存、媒体与 大小校验、SHA-256、source sequence 边界和工作区相对 artifact 引用。采集是 best-effort； Forge ToolResult 与事件仍是权威执行事实。</p><p>第一次绑定物理执行前只执行一次前置采集；全部 task-owned 执行终结后，finalize 才进行后置采集与 聚合验证。仅含 Query 的任务可以保存 Tool facts，但不会伪造 Action capture window。</p><h2 id="_8-skill-runtime" tabindex="-1">8. Skill Runtime <a class="header-anchor" href="#_8-skill-runtime" aria-label="Permalink to &quot;8. Skill Runtime&quot;">​</a></h2><p>Skill Runtime 管理 manifest v2 Bundle 和显式命名 Dora profile。Bundle 使用安全解包、 SHA-256 清单、精确单可执行文件 Node lock、事务替换、持久化状态、生命周期日志以及 Gateway <code>/tools</code> 健康检查。</p><p>Skill 发现优先级为 workspace override、已安装 Skill、内置 Skill。健康活动 Runtime 会把 Skill availability 传给 <code>SkillsLoader</code>、activation、experience 和 evolution；活动 manifest 是 Gateway URL 的唯一来源。</p><p>Registry 下载使用 <code>resourceRegistry.url</code>、<code>PAOS_RESOURCE_REGISTRY_URL</code> 或显式静态 index， 只有显式 CLI 命令和确认后才会发生。PhyAgentOS 分发不包含具体 Forge Skill、Node、模型或 仿真资源。</p><h2 id="_9-experience-与-evolution" tabindex="-1">9. Experience 与 evolution <a class="header-anchor" href="#_9-experience-与-evolution" aria-label="Permalink to &quot;9. Experience 与 evolution&quot;">​</a></h2><p>ExperienceCoordinator 记录全部 Agent tool calls，并把显式 Skill activation、AgentTask、 AgentTask 冻结的 binding/版本、PlanRevision verdict、ToolInvocation 引用、verification attempt 与 evidence reference 归入一条去敏 task episode。</p><p>语义成功可支持受控 Skill candidate；与工作流相关的语义失败可形成规范化 observation 与 作用域 Lesson cluster。基础设施、证据、Verifier、任务不可满足和不确定失败只保留诊断。 Evolution fail-open，不能改变执行或验证结果。</p><h2 id="_10-持久化" tabindex="-1">10. 持久化 <a class="header-anchor" href="#_10-持久化" aria-label="Permalink to &quot;10. 持久化&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;workspace&gt;/</span></span>
<span class="line"><span>├── .paos/agent_tasks/tasks.sqlite3</span></span>
<span class="line"><span>├── .paos/evolution/experience.sqlite3</span></span>
<span class="line"><span>├── .paos/evolution/revisions/&lt;skill&gt;/</span></span>
<span class="line"><span>├── skills/&lt;skill&gt;/SKILL.md</span></span>
<span class="line"><span>└── artifacts/agent_tasks/&lt;task_id&gt;/</span></span>
<span class="line"><span>    ├── before_snapshot.json</span></span>
<span class="line"><span>    ├── after_snapshot.json</span></span>
<span class="line"><span>    ├── evidence_bundle.json</span></span>
<span class="line"><span>    └── evidence/</span></span></code></pre></div><p>Runtime 安装与生命周期状态位于 PAOS 配置的数据路径中，与 AgentTask、evolution 持久化分离。 Runtime 清理不会删除现有 evolution 数据。</p><h2 id="_11-代码地图" tabindex="-1">11. 代码地图 <a class="header-anchor" href="#_11-代码地图" aria-label="Permalink to &quot;11. 代码地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">领域</th><th style="text-align:left;">路径</th></tr></thead><tbody><tr><td style="text-align:left;">Agent Loop 与通用工具</td><td style="text-align:left;"><code>PhyAgentOS/agent/</code></td></tr><tr><td style="text-align:left;">Tool API client、binding 与 AgentTask</td><td style="text-align:left;"><code>PhyAgentOS/forge/tool_client.py</code>、<code>PhyAgentOS/forge/binding.py</code>、<code>PhyAgentOS/forge/task.py</code></td></tr><tr><td style="text-align:left;">Agent Forge tools</td><td style="text-align:left;"><code>PhyAgentOS/agent/tools/forge_tool_api.py</code>、<code>forge_task.py</code></td></tr><tr><td style="text-align:left;">Skill Runtime</td><td style="text-align:left;"><code>PhyAgentOS/skill_runtime/</code></td></tr><tr><td style="text-align:left;">内置 Agent 工作流 Skills</td><td style="text-align:left;"><code>PhyAgentOS/skills/</code></td></tr><tr><td style="text-align:left;">Verification</td><td style="text-align:left;"><code>PhyAgentOS/verification/</code>、<code>PhyAgentOS/agent/session_verifier.py</code></td></tr><tr><td style="text-align:left;">Experience 与 evolution</td><td style="text-align:left;"><code>PhyAgentOS/agent/experience/</code></td></tr></tbody></table><h2 id="_12-当前实现范围" tabindex="-1">12. 当前实现范围 <a class="header-anchor" href="#_12-当前实现范围" aria-label="Permalink to &quot;12. 当前实现范围&quot;">​</a></h2><p>当前 Runtime 通过统一 Tool API 支持 Query、Action 与 Session。跨 Tool 资源租约、Registry 隐式下载和内置具体机器人/仿真制品不在实现契约内。</p><h2 id="后续阅读" tabindex="-1">后续阅读 <a class="header-anchor" href="#后续阅读" aria-label="Permalink to &quot;后续阅读&quot;">​</a></h2><ul><li><a href="/docs/zh/02-user-manual">用户手册</a></li><li><a href="/docs/zh/03-developer-manual">开发者手册</a></li><li><a href="/docs/forge/README_zh">Forge Tool API 接入契约</a></li><li><a href="/docs/zh/05-agent-experience-and-skill-evolution">Agent 经验与 Skill 自进化</a></li></ul>`,43)])])}const u=t(s,[["render",o]]);export{g as __pageData,u as default};
